#include "GraphElements.h"
#include <QFont>
#include <QPointer>
#include <cmath>

void GraphNode::addEdge(GraphEdge *edge) { edgeList.push_back(edge); }
void GraphNode::removeEdge(GraphEdge *edge) {
    for (int i = 0; i < static_cast<int>(edgeList.size()); ++i) {
        if (edgeList[i] == edge) {
            edgeList.erase(edgeList.begin() + i);
            return;
        }
    }
}

GraphEdge::GraphEdge(GraphNode *s, GraphNode *d, bool dir) : source(s), dest(d), is_directed(dir), color(Qt::black) {
    setZValue(-1);
}
QRectF GraphEdge::boundingRect() const {
    if (!source || !dest) return QRectF();
    return QRectF(source->pos(), dest->pos()).normalized().adjusted(-20, -20, 20, 20);
}
void GraphEdge::adjust() {
    if (!source || !dest) return;
    prepareGeometryChange();
}
void GraphEdge::paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) {
    if (!source || !dest) return;
    painter->setRenderHint(QPainter::Antialiasing);
    painter->setPen(QPen(color, 2, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin));
    QLineF line(source->pos(), dest->pos());
    if (line.length() <= 40.0) return;
    qreal rad = std::atan2(line.dy(), line.dx());
    QPointF p1 = source->pos() + QPointF(20 * std::cos(rad), 20 * std::sin(rad));
    QPointF p2 = dest->pos() - QPointF(20 * std::cos(rad), 20 * std::sin(rad));
    painter->drawLine(p1, p2);
    if (is_directed) {
        qreal arrowSize = 12.0;
        QPointF arrowP1 = p2 - QPointF(arrowSize * std::cos(rad - M_PI / 6.0), arrowSize * std::sin(rad - M_PI / 6.0));
        QPointF arrowP2 = p2 - QPointF(arrowSize * std::cos(rad + M_PI / 6.0), arrowSize * std::sin(rad + M_PI / 6.0));
        QPolygonF arrowHead;
        arrowHead << p2 << arrowP1 << arrowP2;
        painter->setBrush(color);
        painter->setPen(QPen(color, 1));
        painter->drawPolygon(arrowHead);
    }
}

GraphEdge::GraphEdge(GraphNode *s, GraphNode *d, bool dir, bool bi) : source(s), dest(d), is_directed(dir), is_bidirectional(bi), weight(0), has_weight(false), color(Qt::black), m_weightLabel(nullptr) {
    setZValue(-1);
    setFlags(ItemIsMovable | ItemSendsGeometryChanges);
    m_weightLabel = new QGraphicsTextItem(this);
    m_weightLabel->setFont(QFont("Consolas", 10, QFont::Bold));
    m_weightLabel->setAcceptedMouseButtons(Qt::NoButton);
    m_weightLabel->setZValue(2);
    m_weightLabel->setVisible(false);
}
void GraphEdge::setWeight(int w) {
    weight = w;
    has_weight = true;
    m_weightLabel->setPlainText(QString::number(w));
    m_weightLabel->setVisible(true);
    refreshLabel();
    update();
}
void GraphEdge::removeWeight() {
    has_weight = false;
    m_weightLabel->setVisible(false);
    update();
}
QPointF GraphEdge::weightAnchor() const {
    if (!source || !dest) return QPointF();
    QPointF p1 = source->pos() - pos();
    QPointF p2 = dest->pos() - pos();
    QPointF delta = p2 - p1;
    qreal length = std::max<qreal>(1.0, std::hypot(delta.x(), delta.y()));
    QPointF offset(-delta.y() / length * 15, delta.x() / length * 15);
    return (p1 + p2) / 2 + offset;
}
void GraphEdge::refreshLabel() {
    if (!m_weightLabel) return;
    m_weightLabel->setPos(weightAnchor() - QPointF(8, 8));
    m_weightLabel->setDefaultTextColor(color);
}
QRectF GraphEdge::boundingRect() const {
    if (!source || !dest) return QRectF();
    QPointF p1 = source->pos() - pos();
    QPointF p2 = dest->pos() - pos();
    QRectF rect = QRectF(p1, p2).normalized().adjusted(-24, -24, 24, 24);
    if (m_weightLabel && m_weightLabel->isVisible()) {
        rect = rect.united(m_weightLabel->boundingRect().translated(m_weightLabel->pos()));
    }
    return rect;
}
void GraphEdge::adjust() {
    if (!source || !dest) return;
    prepareGeometryChange();
    refreshLabel();
}
