QString DijkstraNaiveModule::getDefaultInput() const { return "6 9 1\n1 2 7\n1 3 9\n1 6 14\n2 3 10\n2 4 15\n3 4 11\n3 6 2\n4 5 6\n5 6 9"; }

void DijkstraNaiveModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;
    GraphModuleUtils::GraphInput input;
    m_valid = GraphModuleUtils::parse(inputData, true, true, input);
    if (m_valid) for (const auto& edge : input.edges) if (edge.w < 0) m_valid = false;
    m_mathText = scene->addText(m_valid ? "朴素 Dijkstra：每轮扫描全体未确定点，选择 dist 最小者" : "输入格式：n m src，随后输入 m 条非负权无向边 u v w");
    m_mathText->setFont(QFont("Consolas", 14, QFont::Bold));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(110, 18);
    if (!m_valid) return;
    m_n = input.n;
    m_m = input.m;
    m_src = input.src;
    auto addArc = [this](int u, int v, int weight) {
        int id = ++m_edgeCount;
        m_to[id] = v;
        m_weight[id] = weight;
        m_next[id] = m_head[u];
        m_head[u] = id;
    };
    for (const auto& edge : input.edges) {
        m_edgeList.push_back({edge.u, edge.v, edge.w});
        addArc(edge.u, edge.v, edge.w);
        addArc(edge.v, edge.u, edge.w);
    }
    for (int i = 1; i <= m_n; ++i) {
        GraphNode* node = new GraphNode(i);
        node->setPos(GraphModuleUtils::circlePoint(i - 1, m_n, QPointF(470, 170), m_n <= 8 ? 115 : 135));
        scene->addItem(node);
        m_nodes[i] = node;
    }
    for (const auto& edge : input.edges) {
        auto key = std::make_pair(std::min(edge.u, edge.v), std::max(edge.u, edge.v));
        if (!m_edges.count(key)) {
            GraphEdge* item = new GraphEdge(m_nodes[edge.u], m_nodes[edge.v], false);
            scene->addItem(item);
            m_nodes[edge.u]->addEdge(item);
            m_nodes[edge.v]->addEdge(item);
            m_edges[key] = item;
        }
        QPointF delta = m_nodes[edge.v]->pos() - m_nodes[edge.u]->pos();
        qreal length = std::max<qreal>(1.0, std::hypot(delta.x(), delta.y()));
        QPointF offset(-delta.y() / length * 14, delta.x() / length * 14);
        QGraphicsTextItem* weight = scene->addText(QString::number(edge.w));
        weight->setFont(QFont("Consolas", 10, QFont::Bold));
        weight->setDefaultTextColor(QColor(85, 90, 100));
        weight->setPos((m_nodes[edge.u]->pos() + m_nodes[edge.v]->pos()) / 2 + offset);
        weight->setZValue(2);
        m_weightLabels.push_back(weight);
    }
    QFont labelFont("Microsoft YaHei", 10, QFont::Bold);
    auto addLabel = [scene, labelFont](const QString& text, QPointF pos) {
        QGraphicsTextItem* item = scene->addText(text);
        item->setFont(labelFont);
        item->setDefaultTextColor(QColor(60, 75, 95));
        item->setPos(pos);
        return item;
    };
    int startX = std::max(140, 470 - m_n * 30);
    addLabel("dist", QPointF(35, 348));
    addLabel("settled", QPointF(35, 448));
    addLabel("parent", QPointF(35, 548));
    for (int i = 1; i <= m_n; ++i) {
        int x = startX + (i - 1) * 60;
        ArrayBlock* distance = new ArrayBlock(i, 0, QString("d[%1]").arg(i));
        distance->showValue = false;
        distance->setPos(x, 365);
        scene->addItem(distance);
        m_distBlocks[i] = distance;
        m_distLabels[i] = addLabel("∞", QPointF(x + 16, 371));
        ArrayBlock* done = new ArrayBlock(i, 0, QString("vis[%1]").arg(i));
        done->setPos(x, 465);
        scene->addItem(done);
        m_doneBlocks[i] = done;
        ArrayBlock* parent = new ArrayBlock(i, 0, QString("pre[%1]").arg(i));
        parent->showValue = false;
        parent->setPos(x, 565);
        scene->addItem(parent);
        m_parentBlocks[i] = parent;
        m_parentLabels[i] = addLabel("—", QPointF(x + 21, 571));
    }
    m_pickPointer = new PointerBlock("u", QColor(210, 80, 55));
    m_relaxPointer = new PointerBlock("v", QColor(45, 130, 210));
    m_pickPointer->setOpacity(0);
    m_relaxPointer->setOpacity(0);
    scene->addItem(m_pickPointer);
    scene->addItem(m_relaxPointer);
}

