    auto key = std::make_pair(std::min(frame.u, frame.v), std::max(frame.u, frame.v));
    if (m_edges.count(key) && m_edges[key]->color != QColor(55, 175, 115)) m_edges[key]->setColor(QColor(195, 200, 208));

} else if (frame.type == ActionType::KR_REJECT) {
    GraphEdge* edge = GraphRenderHelper::findEdge(m_edges, frame.u, frame.v);
    if (edge && edge->color != QColor(55, 175, 115)) edge->setColor(QColor(195, 200, 208));

m_edgeList.clear();
m_weightedEdgeList.clear();
m_n = 0;

