    GraphModuleUtils::GraphOptions options = currentModule->getGraphOptions();
    radioDirected->setChecked(options.directed);
    radioUndirected->setChecked(!options.directed);
    bool canBidirectional = currentModule->supportsBidirectional();
    checkBidirectional->setEnabled(canBidirectional);
    checkBidirectional->setChecked(canBidirectional && options.bidirectional);
    radioDirected->setEnabled(currentModule->supportsDirected());
    bool directedChosen = radioDirected->isChecked();
    checkBidirectional->setEnabled(canBidirectional && !directedChosen);
}

