void MainWindow::updateGraphOptionPanel() {
    bool supported = currentModule && currentModule->supportsGraphOptions();
    groupGraphOptions->setVisible(supported);
    if (!supported) return;
    GraphModuleUtils::GraphOptions options = currentModule->getGraphOptions();
    radioDirected->setChecked(options.directed);
    radioUndirected->setChecked(!options.directed);
    bool canDirected = currentModule->supportsDirected();
    radioDirected->setEnabled(canDirected);
    if (!canDirected) radioUndirected->setChecked(true);
    bool canBidirectional = currentModule->supportsBidirectional();
    checkBidirectional->setEnabled(canBidirectional && !radioDirected->isChecked());
    checkBidirectional->setChecked(canBidirectional && options.bidirectional);
}
void MainWindow::applyGraphOptions() {
    if (!currentModule || !currentModule->supportsGraphOptions()) return;
    GraphModuleUtils::GraphOptions options = currentModule->getGraphOptions();
    options.directed = radioDirected->isChecked();
    options.bidirectional = !options.directed && checkBidirectional->isChecked();
    currentModule->setGraphOptions(options);
}
void MainWindow::onGraphOptionChanged() {
    updateGraphOptionPanel();
    applyGraphOptions();
    if (!currentModule) return;
    m_playTimer->stop();
    m_frames.clear();
    m_frameIndex = 0;
    m_recordedInput.clear();
    rebuildCurrentLayout(textInput->toPlainText(), false, false);
    labelStatus->setText("图结构选项已更新，请重新计算动画帧。");
}

void MainWindow::updateGraphOptionPanel() {
    bool supported = currentModule && currentModule->supportsGraphOptions();
    groupGraphOptions->setVisible(supported);
    if (!supported) return;
    GraphModuleUtils::GraphOptions options = currentModule->getGraphOptions();
    bool canDirected = currentModule->supportsDirected();
    bool canBidirectional = currentModule->supportsBidirectional();
    if (!canDirected) {
        radioDirected->setChecked(false);
        radioUndirected->setChecked(true);
    } else {
        radioDirected->setChecked(options.directed);
        radioUndirected->setChecked(!options.directed);
    }
    radioDirected->setEnabled(canDirected);
    radioUndirected->setEnabled(true);
    checkBidirectional->setEnabled(canBidirectional && !radioDirected->isChecked());
    if (!canBidirectional) checkBidirectional->setChecked(false);
    else checkBidirectional->setChecked(options.bidirectional && !radioDirected->isChecked());
}
void MainWindow::applyGraphOptions() {
    if (!currentModule || !currentModule->supportsGraphOptions()) return;
    GraphModuleUtils::GraphOptions options = currentModule->getGraphOptions();
    options.directed = radioDirected->isChecked() && currentModule->supportsDirected();
    options.bidirectional = !options.directed && checkBidirectional->isChecked() && currentModule->supportsBidirectional();
    currentModule->setGraphOptions(options);
}
void MainWindow::onGraphOptionChanged() {
    if (!currentModule) return;
    applyGraphOptions();
    updateGraphOptionPanel();
    m_playTimer->stop();
    m_frames.clear();
    m_frameIndex = 0;
    m_recordedInput.clear();
    rebuildCurrentLayout(textInput->toPlainText(), false, false);
    labelStatus->setText("图结构选项已更新，请重新计算动画帧。");
}

inline GraphEdge* buildOneEdge(QGraphicsScene* scene, std::map<int, GraphNode*>& nodes, std::map<std::pair<int,int>, GraphEdge*>& edges,
                               const GraphModuleUtils::EdgeInput& edge, const GraphModuleUtils::GraphOptions& options, bool weighted) {
    auto key = std::make_pair(edge.u, edge.v);
    auto rev = std::make_pair(edge.v, edge.u);
    bool directed = options.directed;
    bool bidirectional = !options.directed && options.bidirectional;
    if (!directed) {
        key = std::make_pair(std::min(edge.u, edge.v), std::max(edge.u, edge.v));
        if (edges.count(key)) return edges[key];
    } else {
        if (edges.count(key)) return edges[key];
        if (edges.count(rev)) return edges[rev];
    }
    GraphEdge* item = new GraphEdge(nodes[edge.u], nodes[edge.v], directed, bidirectional);
    if (weighted) item->setWeight(edge.w);
    scene->addItem(item);
    nodes[edge.u]->addEdge(item);
    nodes[edge.v]->addEdge(item);
    edges[key] = item;
    return item;
}

inline GraphEdge* buildOneEdge(QGraphicsScene* scene, std::map<int, GraphNode*>& nodes, std::map<std::pair<int,int>, GraphEdge*>& edges,
                               const GraphModuleUtils::EdgeInput& edge, const GraphModuleUtils::GraphOptions& options, bool weighted) {
    bool directed = options.directed;
    bool bidirectional = !options.directed && options.bidirectional;
    auto key = directed ? std::make_pair(edge.u, edge.v) : std::make_pair(std::min(edge.u, edge.v), std::max(edge.u, edge.v));
    auto it = edges.find(key);
    if (it != edges.end()) return it->second;
    GraphEdge* item = new GraphEdge(nodes[edge.u], nodes[edge.v], directed, bidirectional);
    if (weighted) item->setWeight(edge.w);
    scene->addItem(item);
    nodes[edge.u]->addEdge(item);
    nodes[edge.v]->addEdge(item);
    edges[key] = item;
    return item;
}

inline GraphEdge* findEdge(const std::map<std::pair<int,int>, GraphEdge*>& edges, int u, int v) {
    auto it = edges.find(std::make_pair(u, v));
    if (it != edges.end()) return it->second;
    it = edges.find(std::make_pair(v, u));
    if (it != edges.end()) return it->second;
    it = edges.find(std::make_pair(std::min(u, v), std::max(u, v)));
    return it != edges.end() ? it->second : nullptr;
}

inline GraphEdge* findEdge(const std::map<std::pair<int,int>, GraphEdge*>& edges, int u, int v, bool directed = false) {
    auto it = edges.find(std::make_pair(u, v));
    if (it != edges.end()) return it->second;
    if (directed) return nullptr;
    it = edges.find(std::make_pair(v, u));
    if (it != edges.end()) return it->second;
    it = edges.find(std::make_pair(std::min(u, v), std::max(u, v)));
    return it != edges.end() ? it->second : nullptr;
}

