void GraphEdge::paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) {
    if (!source || !dest) return;
    painter->setRenderHint(QPainter::Antialiasing);
    QPointF p0 = source->pos() - pos();
    QPointF p1 = dest->pos() - pos();
    QPointF c = controlPoint() - pos();
    QPainterPath path;
    path.moveTo(p0);
    path.quadTo(c, p1);
    QPen pen(QColor(color.red(), color.green(), color.blue(), m_hovered ? 255 : 220), m_hovered ? 3.5 : 2, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin);
    painter->setPen(pen);
    painter->drawPath(path);
    auto drawArrow = [&](qreal t, bool atEnd) {
        QPointF tip = curvePoint(t);
        QPointF tangent = curveTangent(t);
        if (atEnd) tangent = -tangent;
        qreal length = std::hypot(tangent.x(), tangent.y());
        if (length < 1e-6) return;
        tangent /= length;
        qreal arrowSize = 12.0;
        QPointF base = tip - tangent * arrowSize;
        QPointF p1a = base + QPointF(arrowSize * std::cos(std::atan2(tangent.y(), tangent.x()) + M_PI / 6.0), arrowSize * std::sin(std::atan2(tangent.y(), tangent.x()) + M_PI / 6.0));
        QPointF p2a = base + QPointF(arrowSize * std::cos(std::atan2(tangent.y(), tangent.x()) - M_PI / 6.0), arrowSize * std::sin(std::atan2(tangent.y(), tangent.x()) - M_PI / 6.0));
        QPolygonF head;
        head << tip << p1a << p2a;
        painter->setBrush(color);
        painter->setPen(QPen(color, 1));
        painter->drawPolygon(head);
    };
    if (is_directed || is_bidirectional) drawArrow(1.0, true);
    if (is_bidirectional) drawArrow(0.0, false);
    if (has_weight) {
        QPointF anchor = weightAnchor();
        QRectF badge(anchor.x() - 14, anchor.y() - 11, 28, 22);
        painter->setPen(QPen(color.darker(150), 1.5));
        painter->setBrush(QColor(255, 255, 255));
        painter->drawRoundedRect(badge, 5, 5);
        painter->setPen(color.darker(120));
        painter->setFont(QFont("Consolas", 10, QFont::Bold));
        painter->drawText(badge, Qt::AlignCenter, QString::number(weight));
    }
}

void GraphEdge::paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) {
    if (!source || !dest) return;
    painter->setRenderHint(QPainter::Antialiasing);
    const qreal nodeRadius = 22.0;
    QPointF p0 = trimmedStart(nodeRadius) - pos();
    QPointF p1 = trimmedEnd(nodeRadius) - pos();
    QPointF c = controlPoint() - pos();
    QPainterPath path;
    path.moveTo(p0);
    path.quadTo(c, p1);
    QPen pen(QColor(color.red(), color.green(), color.blue(), m_hovered ? 255 : 220), m_hovered ? 3.5 : 2, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin);
    painter->setPen(pen);
    painter->drawPath(path);
    auto drawArrow = [&](QPointF tip, QPointF dir) {
        qreal length = std::hypot(dir.x(), dir.y());
        if (length < 1e-6) return;
        QPointF tangent = dir / length;
        qreal arrowSize = 13.0;
        QPointF base = tip - tangent * arrowSize;
        qreal ang = std::atan2(tangent.y(), tangent.x());
        QPointF p1a = base + QPointF(arrowSize * std::cos(ang + M_PI / 6.0), arrowSize * std::sin(ang + M_PI / 6.0));
        QPointF p2a = base + QPointF(arrowSize * std::cos(ang - M_PI / 6.0), arrowSize * std::sin(ang - M_PI / 6.0));
        QPolygonF head;
        head << tip << p1a << p2a;
        painter->setBrush(color);
        painter->setPen(QPen(color, 1));
        painter->drawPolygon(head);
    };
    if (is_directed || is_bidirectional) {
        QPointF tip = trimmedEnd(nodeRadius);
        QPointF dir = tip - (controlPoint() - tip);
        drawArrow(tip - pos(), dir);
    }
    if (is_bidirectional) {
        QPointF tip = trimmedStart(nodeRadius);
        QPointF dir = tip - (controlPoint() - tip);
        drawArrow(tip - pos(), dir);
    }
    if (has_weight) {
        QPointF anchor = weightAnchor() - pos();
        painter->setPen(color.darker(120));
        painter->setFont(QFont("Consolas", 11, QFont::Bold));
        painter->drawText(QRectF(anchor.x() - 30, anchor.y() - 11, 60, 22), Qt::AlignCenter, QString::number(weight));
    }
}

QPainterPath GraphEdge::shape() const {
    QPainterPath path;
    if (!source || !dest) return path;
    path.moveTo(source->pos() - pos());
    path.quadTo(controlPoint() - pos(), dest->pos() - pos());
    QPainterPathStroker stroker;
    stroker.setWidth(12);
    return stroker.createStroke(path);
}
QRectF GraphEdge::boundingRect() const {
    if (!source || !dest) return QRectF();
    QRectF rect = QRectF(source->pos(), dest->pos()).normalized().adjusted(-30, -30, 30, 30);
    rect = rect.united(QRectF(controlPoint(), QPointF(0, 0)).adjusted(-30, -30, 30, 30));
    if (has_weight) rect = rect.united(QRectF(weightAnchor() - QPointF(16, 12), QPointF(32, 24)));
    return rect;
}

QPainterPath GraphEdge::shape() const {
    QPainterPath path;
    if (!source || !dest) return path;
    path.moveTo(trimmedStart(22.0) - pos());
    path.quadTo(controlPoint() - pos(), trimmedEnd(22.0) - pos());
    QPainterPathStroker stroker;
    stroker.setWidth(12);
    return stroker.createStroke(path);
}
QRectF GraphEdge::boundingRect() const {
    if (!source || !dest) return QRectF();
    QRectF rect = QRectF(source->pos(), dest->pos()).normalized().adjusted(-30, -30, 30, 30);
    rect = rect.united(QRectF(controlPoint(), QPointF(0, 0)).adjusted(-30, -30, 30, 30));
    if (has_weight) rect = rect.united(QRectF(weightAnchor() - QPointF(30, 11), QPointF(60, 22)));
    return rect;
}

