static QImage renderScene(QGraphicsScene* scene, int w, int h) {
    QImage img(w, h, QImage::Format_ARGB32);
    img.fill(Qt::white);
    QPainter p(&img);
    scene->render(&p, QRectF(0, 0, w, h));
    p.end();
    return img;
}

static int countDark(const QImage& img, QRectF region) {
    int n = 0;
    QRect r = region.toRect().intersected(img.rect());
    for (int y = r.top(); y <= r.bottom(); ++y)
        for (int x = r.left(); x <= r.right(); ++x) {
            QColor c = img.pixelColor(x, y);
            if (c.red() < 120 && c.green() < 120 && c.blue() < 120) n++;
        }
    return n;
}

