void GraphNode::mouseMoveEvent(QGraphicsSceneMouseEvent *event) {
    if (m_dragging && scene()) {
        SceneGrid::Config cfg = SceneGrid::currentConfig();
        if (cfg.enabled && !event->modifiers().testFlag(Qt::ControlModifier)) {
            QPointF proposed = m_dragOrigin + (event->scenePos() - event->scenePos());
            QPointF snapped = SceneGrid::magneticAlign(scene(), this, event->scenePos() - m_pressScenePos + m_dragOrigin, cfg);
            setPos(snapped);
            event->accept();
            return;
        }
    }
    QGraphicsObject::mouseMoveEvent(event);
}
