void MainWindow::adjustSceneBoundary(bool centerView) {
    QRectF itemsRect = graphicsScene->itemsBoundingRect();
    if (itemsRect.isNull()) {
        itemsRect = QRectF(0, 0, 800, 600);
    }
    QRectF safeRect = itemsRect.adjusted(-800, -800, 800, 800);
    graphicsScene->setSceneRect(safeRect);
    if (centerView) {
        graphicsView->resetTransform();
        graphicsView->centerOn(itemsRect.center());
    }
}

void MainWindow::adjustSceneBoundary(bool centerView) {
    QRectF itemsRect = graphicsScene->itemsBoundingRect();
    if (itemsRect.isNull() || itemsRect.width() < 1 || itemsRect.height() < 1) {
        itemsRect = QRectF(-400, -300, 800, 600);
    }
    QRectF safeRect = itemsRect.adjusted(-800, -800, 800, 800);
    graphicsScene->setSceneRect(safeRect);
    if (!centerView) return;

    graphicsView->resetTransform();
    QRectF viewport = graphicsView->viewport()->rect();
    QRectF target = itemsRect.adjusted(-70, -70, 70, 70);
    graphicsView->fitInView(target, Qt::KeepAspectRatio);
    qreal scale = graphicsView->transform().m11();
    if (scale < 0.25) {
        graphicsView->resetTransform();
        graphicsView->scale(0.25, 0.25);
    } else if (scale > 2.4) {
        graphicsView->resetTransform();
        graphicsView->scale(2.4, 2.4);
    }
    QPointF center = graphicsView->mapFromScene(itemsRect.center());
    graphicsView->centerOn(graphicsView->mapToScene(center));
    Q_UNUSED(viewport);
}

    QPointF center = graphicsView->mapFromScene(itemsRect.center());
    graphicsView->centerOn(graphicsView->mapToScene(center));
    Q_UNUSED(viewport);
}

    graphicsView->centerOn(itemsRect.center());
    Q_UNUSED(viewport);
}

