void MainWindow::adjustSceneBoundary(bool centerView) {
    QRectF itemsRect = graphicsScene->itemsBoundingRect();
    if (itemsRect.isNull() || itemsRect.width() < 1 || itemsRect.height() < 1) {
        itemsRect = QRectF(-400, -300, 800, 600);
    }
    QRectF safeRect = itemsRect.adjusted(-800, -800, 800, 800);
    graphicsScene->setSceneRect(safeRect);
    if (!centerView) return;

    graphicsView->resetTransform();
    QRectF viewport = graphicsView->viewport()->rect();
    QRectF target = itemsRect.adjusted(-70, -70, 70, 70);
    graphicsView->fitInView(target, Qt::KeepAspectRatio);
    qreal scale = graphicsView->transform().m11();
    if (scale < 0.25) {
        graphicsView->resetTransform();
        graphicsView->scale(0.25, 0.25);
    } else if (scale > 2.4) {
        graphicsView->resetTransform();
        graphicsView->scale(2.4, 2.4);
    }
    graphicsView->centerOn(itemsRect.center());
    Q_UNUSED(viewport);
}

void MainWindow::adjustSceneBoundary(bool centerView) {
    ViewportFitter::Options options;
    ViewportFitter::expandSceneRect(graphicsScene, options);
    if (centerView) {
        ViewportFitter::fitToItems(graphicsView, graphicsScene, options);
    }
}

GraphEdge* IModule::createEdge(GraphNode* u, GraphNode* v, const GraphModuleUtils::GraphOptions& options, const GraphModuleUtils::EdgeInput& edge, bool hasWeight) {
    if (!u || !v || !m_scene) return nullptr;
    bool directed = options.directed;
    bool bidirectional = !options.directed && options.bidirectional;
    GraphEdge* item = new GraphEdge(u, v, directed, bidirectional);
    if (hasWeight) item->setWeight(edge.w);
    m_scene->addItem(item);
    u->addEdge(item);
    v->addEdge(item);
    return item;
}

