class ArrayBlock : public QGraphicsObject {
    Q_OBJECT
public:
    int id;
    int value;
    bool showValue;
    QColor color;
    QString customLabel;
    ArrayBlock(int _id, int _val, QString _label = "");
    QRectF boundingRect() const override;
    void paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) override;
};

class ArrayBlock : public QGraphicsObject {
    Q_OBJECT
public:
    int id;
    int value;
    bool showValue;
    QColor color;
    QString customLabel;
    bool showLabel;
    ArrayBlock(int _id, int _val, QString _label = "");
    void setShowLabel(bool on) { showLabel = on; update(); }
    void setCustomLabel(const QString& text) { customLabel = text; update(); }
    QRectF boundingRect() const override;
    void paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) override;
};

ArrayBlock::ArrayBlock(int _id, int _val, QString _label) : id(_id), value(_val), showValue(true), color(Qt::white), customLabel(_label) {
    setZValue(1);
}
QRectF ArrayBlock::boundingRect() const {
    return QRectF(-10, -30, 80, 80);
}

void ArrayBlock::paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) {
    painter->setRenderHint(QPainter::Antialiasing);
    painter->setBrush(color);
    painter->setPen(QPen(Qt::black, 2));
    painter->drawRect(0, 0, 60, 40);

    painter->setFont(QFont("Consolas", 14, QFont::Bold));
    if (showValue) {
        painter->drawText(QRectF(0, 0, 60, 40), Qt::AlignCenter, QString::number(value));
    }

    painter->setFont(QFont("Consolas", 12));
    QString topText = customLabel.isEmpty() ? QString::number(id) : customLabel;
    painter->drawText(QRectF(0, -25, 60, 20), Qt::AlignHCenter | Qt::AlignBottom, topText);
}

ArrayBlock::ArrayBlock(int _id, int _val, QString _label) : id(_id), value(_val), showValue(true), color(Qt::white), customLabel(_label), showLabel(true) {
    setZValue(1);
}
QRectF ArrayBlock::boundingRect() const {
    return QRectF(-10, -30, 80, 80);
}

void ArrayBlock::paint(QPainter *painter, const QStyleOptionGraphicsItem *, QWidget *) {
    painter->setRenderHint(QPainter::Antialiasing);
    painter->setBrush(color);
    painter->setPen(QPen(Qt::black, 2));
    painter->drawRect(0, 0, 60, 40);

    painter->setFont(QFont("Consolas", 14, QFont::Bold));
    if (showValue) {
        painter->drawText(QRectF(0, 0, 60, 40), Qt::AlignCenter, QString::number(value));
    }

    if (!showLabel) return;
    painter->setFont(QFont("Consolas", 12));
    QString topText = customLabel.isEmpty() ? QString::number(id) : customLabel;
    painter->drawText(QRectF(0, -25, 60, 20), Qt::AlignHCenter | Qt::AlignBottom, topText);
}

inline QGraphicsTextItem* addLabel(QGraphicsScene* scene, const QString& text, QPointF pos, int size = 10) {
    QGraphicsTextItem* item = scene->addText(text);
    item->setFont(QFont("Microsoft YaHei", size, QFont::Bold));
    item->setDefaultTextColor(QColor(60, 75, 95));
    item->setPos(pos);
    return item;
}

inline QGraphicsTextItem* addLabel(QGraphicsScene* scene, const QString& text, QPointF pos, int size = 10) {
    QGraphicsTextItem* item = scene->addText(text);
    item->setFont(QFont("Microsoft YaHei", size, QFont::Bold));
    item->setDefaultTextColor(QColor(60, 75, 95));
    item->setPos(pos);
    return item;
}

inline QGraphicsTextItem* addAxisLabel(QGraphicsScene* scene, const QString& text, QPointF pos, int size = 10, const QColor& color = QColor(80, 92, 110)) {
    QGraphicsTextItem* item = scene->addText(text);
    QFont f("Microsoft YaHei UI");
    if (f.family().isEmpty() || f.family().contains("Sans")) f = QFont("Segoe UI");
    f.setPointSize(size);
    f.setBold(true);
    f.setStyleStrategy(QFont::PreferQuality);
    item->setFont(f);
    item->setDefaultTextColor(color);
    item->setPos(pos);
    return item;
}

