    $exes = Get-ChildItem -Path $TestDir -Filter "*.exe" -ErrorAction SilentlyContinue
    foreach ($f in $exes) {
        $out = & $f.FullName 2>&1 | Out-String
        if ($LASTEXITCODE -ne 0) {
            $fails += $f.Name
            Write-Host "FAIL: $($f.Name)"
