        }
    }
    Write-Host "count=$($exes.Count)"
    if ($fails.Count -eq 0) {
        Write-Host "ALL SUITES PASS"
        exit 0
    }
    Write-Host "FAILED: $($fails -join ', ')"
    exit 1
}

