void IModule::playScalePulse(QGraphicsItem* item, qreal peak, int duration) {
    if (!item) return;
    if (!m_animated) {
        item->setScale(1.0);
        return;
    }
    QPropertyAnimation* anim = acquireAnim(static_cast<QObject*>(item), "scale", duration, QEasingCurve::InOutQuad);
    if (!anim) return;
    anim->setStartValue(item->scale());
    anim->setKeyValueAt(0.0, 1.0);
    anim->setKeyValueAt(0.5, peak);
    anim->setKeyValueAt(1.0, 1.0);
    anim->start();
}

void IModule::playScalePulse(QObject* item, qreal peak, int duration) {
    if (!item) return;
    if (!m_animated) {
        if (QGraphicsItem* g = qobject_cast<QGraphicsItem*>(item)) g->setScale(1.0);
        return;
    }
    QPropertyAnimation* anim = acquireAnim(item, "scale", duration, QEasingCurve::InOutQuad);
    if (!anim) return;
    QGraphicsItem* g = qobject_cast<QGraphicsItem*>(item);
    anim->setStartValue(g ? g->scale() : 1.0);
    anim->setKeyValueAt(0.0, 1.0);
    anim->setKeyValueAt(0.5, peak);
    anim->setKeyValueAt(1.0, 1.0);
    anim->start();
}

