void IModule::refreshLiveSlots() {
    if (!m_scene) return;
    for (QGraphicsItem* item : m_scene->items()) {
        ArrayBlock* block = qgraphicsitem_cast<ArrayBlock*>(item);
        if (block) {
            QString row = editableRowFor(block);
            if (row.isEmpty()) continue;
            int value = block->value;
            if (EditableModel::instance().getValue(liveScope(), row, block->id, value)) {
                block->value = value;
                block->customValue.clear();
                block->showValue = true;
            }
            block->update();
            continue;
        }
        GraphNode* node = qgraphicsitem_cast<GraphNode*>(item);
        if (node) {
            QString row = editableRowFor(node);
            if (row.isEmpty()) continue;
            int value = node->value;
            if (EditableModel::instance().getValue(liveScope(), row, node->id, value)) {
                node->value = value;
                node->valueText = QString::number(value);
            }
            node->update();
            continue;
        }
        GraphEdge* edge = qgraphicsitem_cast<GraphEdge*>(item);
        if (edge) {
            QString row = editableRowFor(edge);
            if (row.isEmpty()) continue;
            int value = edge->weight;
            if (EditableModel::instance().getValue(liveScope(), row, edge->weight, value)) {
                edge->weight = value;
            }
            edge->update();
        }
    }
}

