        double gap = 6.0;
        double span = totalWidth + gap * (count - 1);
        double cursor = base_x - span / 2.0;
        for (int i = 0; i < count; ++i) {
            double targetPos_x = cursor + half[i];
            cursor += half[i] * 2.0 + gap;
            QPointF targetPos(targetPos_x, yPos);
            if (m_animated) {
                QPropertyAnimation* anim = acquireAnim(group[i], "pos", 400, QEasingCurve::InOutQuad);
                if (!anim) continue;
                anim->setStartValue(group[i]->pos());
                anim->setEndValue(targetPos);
                anim->start();
            } else {
                stopAnimFor(group[i]);
                group[i]->setPos(targetPos);
            }
        }
    }
}

