void ComboTile::paintEvent(QPaintEvent*) {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);
    QRectF box = QRectF(rect()).adjusted(0.5, 0.5, -0.5, -0.5);
    QPainterPath path;
    path.addRoundedRect(box, 8.0, 8.0);
    if (m_selected) {
        painter.setPen(QPen(UiTheme::accent().darker(125), 1.2));
        painter.setBrush(UiTheme::accentSoft());
    } else if (m_hover) {
        painter.setPen(QPen(UiTheme::borderStrong(), 1));
        painter.setBrush(UiTheme::surfaceHover());
    } else {
        painter.setPen(QPen(QColor(230, 234, 241), 1));
        painter.setBrush(QColor(250, 251, 253));
    }
    painter.drawPath(path);
    painter.setFont(font());
    painter.setPen(m_selected ? UiTheme::accent().darker(125) : UiTheme::textSecondary());
    painter.drawText(QRectF(6, 0, width() - 12, height()), Qt::AlignVCenter | Qt::AlignHCenter, m_text);
