    if (!m_popupLayout) return;
    for (ComboRow* row : m_rows) {
        m_popupLayout->removeWidget(row);
        row->deleteLater();
    }
    m_rows.clear();
    for (int i = 0; i < m_items.size(); ++i) {
        ComboRow* row = new ComboRow(m_items[i], m_popupContent);
        row->setSelected(i == m_current);
        connect(row, &ComboRow::picked, this, [this, i]() {
            setCurrentIndex(i);
            closePopup();
        });
        m_popupLayout->addWidget(row);
        m_rows.push_back(row);
    }
}

void MyComboBox::rebuildRows() {
    if (!m_popupLayout) return;
    for (ComboRow* row : m_rows) {
        m_popupLayout->removeWidget(row);
        row->deleteLater();
    }
    m_rows.clear();
    for (QWidget* w : m_popupWidgets) {
        m_popupLayout->removeWidget(w);
        w->deleteLater();
    }
    m_popupWidgets.clear();

    if (m_groups.isEmpty()) {
        for (int i = 0; i < m_items.size(); ++i) {
            ComboRow* row = new ComboRow(m_items[i], m_popupContent);
            row->setSelected(i == m_current);
            connect(row, &ComboRow::picked, this, [this, i]() {
                setCurrentIndex(i);
                closePopup();
            });
            m_popupLayout->addWidget(row);
            m_rows.push_back(row);
        }
        return;
    }

    QVector<int> placed;
    placed.reserve(m_items.size());
    for (const Group& group : m_groups) {
        ComboSectionHeader* header = new ComboSectionHeader(group.name, m_popupContent);
        m_popupLayout->addWidget(header);
        m_popupWidgets.push_back(header);

        QGridLayout* grid = new QGridLayout();
        grid->setContentsMargins(12, 2, 12, 8);
        grid->setHorizontalSpacing(8);
        grid->setVerticalSpacing(8);
        const int columns = 3;
        int cell = 0;
        for (int index : group.indices) {
            ComboTile* tile = new ComboTile(m_items[index], m_popupContent);
            tile->setSelected(index == m_current);
            connect(tile, &ComboTile::picked, this, [this, index]() {
                setCurrentIndex(index);
                closePopup();
            });
            grid->addWidget(tile, cell / columns, cell % columns);
            ++cell;
        }
        m_popupLayout->addLayout(grid);
    }
}

