bool MyComboBox::eventFilter(QObject* obj, QEvent* event) {
    if (m_popup && event->type() == QEvent::MouseButtonPress) {
        QMouseEvent* me = static_cast<QMouseEvent*>(event);
        QWidget* w = qobject_cast<QWidget*>(obj);
        if (w != m_popup && !isAncestorOf(w)) {
            bool insidePopup = false;
            for (ComboRow* row : m_rows) {
                if (w == row || (w && row->isAncestorOf(w))) { insidePopup = true; break; }
            }
            if (!insidePopup) {
                closePopup();
                qApp->removeEventFilter(this);
                Q_UNUSED(me);
            }
        }
    }

bool MyComboBox::isPopupChild(QObject* obj) const {
    QWidget* w = qobject_cast<QWidget*>(obj);
    if (!w) return false;
    if (w == m_popup) return true;
    if (m_popup && m_popup->isAncestorOf(w)) return true;
    for (ComboRow* row : m_rows) {
        if (w == row || (w && row->isAncestorOf(w))) return true;
    }
    for (QWidget* child : m_popupWidgets) {
        if (w == child || (w && child->isAncestorOf(w))) return true;
    }
    return false;
}

bool MyComboBox::eventFilter(QObject* obj, QEvent* event) {
    if (m_popup && event->type() == QEvent::MouseButtonPress) {
        QMouseEvent* me = static_cast<QMouseEvent*>(event);
        QWidget* w = qobject_cast<QWidget*>(obj);
        if (w != m_popup && !isAncestorOf(w) && !isPopupChild(w)) {
            closePopup();
            qApp->removeEventFilter(this);
            Q_UNUSED(me);
        }
    }

void MyComboBox::closePopup() {
    if (!m_popup) return;
    QPointer<QWidget> popup = m_popup;
    m_popup = nullptr;
    m_popupLayout = nullptr;
    m_rows.clear();
    if (!popup) return;
    popup->close();
    popup->deleteLater();
}

