void GraphNode::commitEdit() {
    if (m_editor.isNull()) return;
    QString text = m_editor->toPlainText().trimmed();
    destroyEditor(m_editor);
    update();
    if (text.isEmpty()) return;
    bool ok = false;
    int parsed = text.toInt(&ok);
    if (ok) {
        value = parsed;
        if (!customValueText.isEmpty()) setCustomValueText(QString::number(parsed));
        else setValueText(QString("v:%1").arg(parsed));
    } else {
        if (!customValueText.isEmpty()) setCustomValueText(text);
        else setValueText(text);
    }
    update();
    emit valueEdited(id, text);
}

