void MainWindow::setupCanvasTools() {
    if (!m_toolController) return;

    connect(m_toolController, &ToolController::toolChanged, this, [this](ToolController::Tool tool) {
        syncAnnotationToolButtons(static_cast<int>(tool));
        labelStatus->setText(QString("当前画布工具: %1").arg(toolName(tool)));
    });
    connect(m_toolController, &ToolController::statusMessage, this, [this](const QString& text) {
        labelStatus->setText(text);
    });

    m_btnExportPdf = new MyButton("导出 PDF", canvasHost);
    m_btnExportPdf->setObjectName("canvasExportButton");
    m_btnExportPdf->setVariant(MyButton::Soft);
    m_btnExportPdf->setCompact(true);
    connect(m_btnExportPdf, &MyButton::clicked, this, &MainWindow::onExportPdf);

    m_btnClearAnnotations = new MyButton("清空批注", canvasHost);
    m_btnClearAnnotations->setObjectName("canvasClearButton");
    m_btnClearAnnotations->setVariant(MyButton::Ghost);
    m_btnClearAnnotations->setCompact(true);
    connect(m_btnClearAnnotations, &MyButton::clicked, this, &MainWindow::onClearAnnotations);

    m_btnToggleAnnotations = new MyButton("隐藏批注", canvasHost);
    m_btnToggleAnnotations->setObjectName("canvasVisibilityButton");
    m_btnToggleAnnotations->setVariant(MyButton::Ghost);
    m_btnToggleAnnotations->setCompact(true);
    connect(m_btnToggleAnnotations, &MyButton::clicked, this, &MainWindow::onAnnotationVisibilityToggled);

    m_btnLockAnnotations = new MyButton("锁定批注", canvasHost);
    m_btnLockAnnotations->setObjectName("canvasLockButton");
    m_btnLockAnnotations->setVariant(MyButton::Ghost);
    m_btnLockAnnotations->setCompact(true);
    connect(m_btnLockAnnotations, &MyButton::clicked, this, &MainWindow::onAnnotationLockToggled);

    if (m_canvasToolBar && m_canvasToolBar->layout()) {
        m_canvasToolBar->layout()->addWidget(m_btnExportPdf);
        m_canvasToolBar->layout()->addWidget(m_btnClearAnnotations);
        m_canvasToolBar->layout()->addWidget(m_btnToggleAnnotations);
        m_canvasToolBar->layout()->addWidget(m_btnLockAnnotations);
    }
}

void MainWindow::syncAnnotationToolButtons(int tool) {
    Q_UNUSED(tool);
}

QString MainWindow::toolName(ToolController::Tool tool) const {
    switch (tool) {
    case ToolController::Select: return "指针（可拖动下层算法结构）";
    case ToolController::AnnotationSelect: return "选中（框选并移动上层批注）";
    case ToolController::Pen: return "画笔";
    case ToolController::Eraser: return "橡皮（只擦除上层批注）";
    case ToolController::Line: return "直线（Shift 约束 45 度）";
    case ToolController::Rect: return "方框（Shift 为正方形）";
    case ToolController::Circle: return "圆形（Shift 为正圆）";
    case ToolController::Arrow: return "箭头（Shift 约束 45 度）";
    case ToolController::Triangle: return "三角形（Shift 为正三角形）";
    case ToolController::Mosaic: return "马赛克";
    case ToolController::TextBox: return "文本框（双击编辑）";
    case ToolController::Markdown: return "Markdown 笔记（双击编辑）";
    case ToolController::Latex: return "LaTeX 公式";
    case ToolController::Table: return "表格（双击单元格编辑）";
    default: return "指针";
    }
}

void MainWindow::onExportPdf() {
    const QString path = QFileDialog::getSaveFileName(this, "导出画布为 PDF", QString(), "PDF 文件 (*.pdf)");
    if (path.isEmpty()) return;
    exportCanvasToPdf(path);
}

void MainWindow::exportCanvasToPdf(const QString& path) {
    if (!graphicsScene) return;

    QRectF base = graphicsScene->itemsBoundingRect();
    QRectF overlay;
    if (m_annotationScene) overlay = m_annotationScene->itemsBoundingRect();
    QRectF total = base;
    if (!overlay.isNull()) total = total.united(overlay);
    if (total.isNull() || total.width() < 1.0 || total.height() < 1.0) {
        labelStatus->setText("画布为空，没有可导出的内容。");
        return;
    }
    const qreal margin = 40.0;
    total.adjust(-margin, -margin, margin, margin);

    const qreal dpi = 96.0;
    QPdfWriter writer(path);
    writer.setResolution(dpi);
    const QSizeF pageSizePt = writer.pageLayout().pageSize();
    const qreal pageW = pageSizePt.width();
    const qreal pageH = pageSizePt.height();

    const qreal scale = qMin(pageW / total.width(), pageH / total.height());
    writer.setPageSize(QPageSize(QSizeF(total.width() * scale, total.height() * scale),
                                 QPageSize::Point));
    writer.setPageMargins(QMarginsF(0, 0, 0, 0));

    QPainter painter;
    if (!painter.begin(&writer)) {
        labelStatus->setText("PDF 导出失败：无法写入文件。");
        return;
    }
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setRenderHint(QPainter::TextAntialiasing);
    painter.fillRect(painter.viewport(), UiTheme::canvasBg());

    const QRectF pageRect = painter.viewport();
    painter.translate(pageRect.left(), pageRect.top());
    painter.scale(scale, scale);
    painter.translate(-total.left(), -total.top());

    graphicsScene->render(&painter, targetRect(base), base, Qt::IgnoreAspectRatio);
    if (m_annotationScene && !overlay.isNull()) {
        m_annotationScene->render(&painter, targetRect(overlay), overlay, Qt::IgnoreAspectRatio);
    }
    painter.end();
    labelStatus->setText(QString("已导出 PDF: %1").arg(path));
}

