                      Qt::MouseButton button, Qt::KeyboardModifiers mods) {
    QPointF local = view->mapFromScene(scenePos);
    QGraphicsSceneMouseEvent ev(type);
    ev.setScenePos(scenePos);
    ev.setPos(local);
    ev.setButton(button);
    ev.setButtons(type == QEvent::MouseButtonRelease ? Qt::MouseButtons() : Qt::MouseButtons(button));
    ev.setModifiers(mods);
    QApplication::sendEvent(view->viewport(), &ev);
}

