void AnnotationItem::scaleBy(qreal factor, const QPointF& pivot) {
    if (factor <= 0.001) return;
    prepareGeometryChange();
    setScale(scale() * factor);
    const QPointF local = mapFromScene(pivot);
    setPos(pos() + mapToParent(local) - local);
    update();
}

