        if (event->modifiers().testFlag(Qt::ControlModifier)) {
            if (event->key() == Qt::Key_Z) {
                if (event->modifiers().testFlag(Qt::ShiftModifier)) m_toolController->redo();
                else m_toolController->undo();
                return;
