void ToolIconButton::mousePressEvent(QMouseEvent* event) {
    if (event->button() == Qt::LeftButton) {
        m_pressed = true;
        update();
        event->accept();
        return;
    }
    QAbstractButton::mousePressEvent(event);
}

void ToolIconButton::mouseReleaseEvent(QMouseEvent* event) {
    if (event->button() == Qt::LeftButton) {
        const bool wasPressed = m_pressed;
        m_pressed = false;
        update();
        if (wasPressed && rect().contains(event->position().toPoint())) {
            emit clicked();
            event->accept();
            return;
        }
    }
    QAbstractButton::mouseReleaseEvent(event);
}

void CanvasToolBar::placePanel(QWidget* panel, int barX, int barW, int barY, int barH) {
    if (!panel || !m_host) return;
    panel->adjustSize();
    const int panelW = panel->sizeHint().width();
    const int panelH = panel->sizeHint().height();
    const int areaW = m_host->width();
    const int areaH = m_host->height();
    const int px = qBound(8, barX + barW - panelW, qMax(8, areaW - panelW - 8));
    int py = barY + barH + 10;
    if (py + panelH > areaH - 8) py = qMax(8, barY - panelH - 10);
    panel->setGeometry(px, py, panelW, panelH);
}

