void ToolController::onKeyPress(QKeyEvent* event) {
    const bool ctrl = event->modifiers().testFlag(Qt::ControlModifier);
    if (!ctrl) return;
    if (event->key() == Qt::Key_Z) {
        if (event->modifiers().testFlag(Qt::ShiftModifier)) redo();
        else undo();
        event->accept();
        return;
    }
    if (event->key() == Qt::Key_Y) {
        redo();
        event->accept();
        return;
    }
}

