QPixmap CanvasView::captureSceneRegion(const QRectF& region) const {
    if (region.isEmpty()) return QPixmap();
    const QPointF topLeft = mapToScene(QPoint(0, 0));
    const QPointF bottomRight = mapToScene(QPoint(width(), height()));
    const QRectF viewRect(topLeft, bottomRight).normalized();
    const QRectF clipped = region.intersected(viewRect);
    if (clipped.isEmpty()) return QPixmap();

    const QSize size = clipped.size().toSize();
    if (size.isEmpty()) return QPixmap();

    QPixmap pixmap(size);
    pixmap.fill(Qt::transparent);

    QPainter painter(&pixmap);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setRenderHint(QPainter::SmoothPixmapTransform);
    painter.translate(-clipped.topLeft());
    const QTransform t = transform();
    painter.setWorldTransform(t, true);
    painter.setWorldTransform(QTransform(), true);
    painter.setWindow(QRectF(region), QRectF(region));
    if (scene()) scene()->render(&painter, region, region, Qt::KeepAspectRatio);
    painter.end();
    return pixmap;
}

