void CanvasToolBar::buildToolPanel() {
    m_toolPanel = new ToolCard(m_host ? m_host : this);
    m_toolPanel->setObjectName("canvasToolPanel");
    m_toolPanel->setAttribute(Qt::WA_TranslucentBackground, true);
    rebuildToolPanelContent();
}

void CanvasToolBar::rebuildToolPanelContent() {
    if (!m_toolPanel) return;
    if (!m_toolPanelLayout) {
        m_toolPanelLayout = new QVBoxLayout(m_toolPanel);
        m_toolPanelLayout->setContentsMargins(15, 13, 15, 13);
        m_toolPanelLayout->setSpacing(8);
    }
    QVBoxLayout* layout = m_toolPanelLayout;

    while (layout->count() > 0) {
        QLayoutItem* item = layout->takeAt(0);
        if (!item) continue;
        if (QWidget* w = item->widget()) {
            w->setParent(nullptr);
            w->deleteLater();
        }
        delete item;
    }

    const ToolController::Tool tool = m_controller->currentTool();

    auto addSliderRow = [this, layout](const QString& label, int min, int max, int value,
                                       const QString& objectName,
                                       const std::function<void(int)>& sink) {
        QHBoxLayout* row = new QHBoxLayout();
        row->setSpacing(8);
        QLabel* text = makePanelLabel(label, m_toolPanel);
        text->setFixedWidth(52);
        row->addWidget(text);
        MySlider* slider = new MySlider(m_toolPanel);
        slider->setObjectName(objectName);
        slider->setRange(min, max);
        slider->setValue(value);
        slider->setFixedWidth(132);
        connect(slider, &MySlider::valueChanged, this, [sink](int v) { sink(v); });
        row->addWidget(slider, 1);
        layout->addLayout(row);
