void CanvasToolBar::showToolPage(ToolController::Tool tool) {
    if (!m_toolPages) return;
    const int count = m_toolPages->count();
    for (int i = 0; i < count; ++i) {
        QWidget* page = m_toolPages->widget(i);
        if (!page) continue;
        if (page->objectName() == QString("canvasToolPage_%1").arg(static_cast<int>(tool))) {
            m_toolPages->setCurrentIndex(i);
            return;
        }
    }
}

if (m_toolPanel) {
