            printf("   child %s geom=%d,%d %dx%d vis=%d\n",
                   c->objectName().toLatin1().constData(),
                   c->x(), c->y(), c->width(), c->height(), c->isVisible());
        }
    } else {
        m_toolPanel->hide();
    }
}

if (m_toolPanel) {
