    m_document.setPlainText(m_source);
    if (m_textItem) {
        m_textItem->setTextInteractionFlags(Qt::TextEditorInteraction);
        m_textItem->setFocus();
        QTextCursor cursor = m_textItem->textCursor();
        cursor.select(QTextCursor::Document);
        m_textItem->setTextCursor(cursor);
    }
    update();
    return true;
