void MarkdownItem::commitInlineEdit() {
    if (!m_editing) return;
    m_editing = false;
    m_source = m_document.toPlainText();
    if (m_textItem) m_textItem->setTextInteractionFlags(Qt::NoTextInteraction);
    rebuildDocument();
    update();
}

void MarkdownItem::cancelInlineEdit() {
    if (!m_editing) return;
    m_editing = false;
    if (m_textItem) m_textItem->setTextInteractionFlags(Qt::NoTextInteraction);
    rebuildDocument();
    update();
}

