    const QTextLayout* layout = block.layout();
    if (!layout) return QRectF();
    const int offset = m_cursor.position() - block.position();
    const int lineNo = layout->lineNumberForTextPosition(offset);
    const QTextLine line = layout->lineAt(lineNo);
    if (!line.isValid()) return QRectF();
    const qreal x = line.x() + line.cursorToX(offset);
    const QRectF lineRect = line.rect();
    return QRectF(x, lineRect.top(), 1.4, lineRect.height());
}

void MarkdownItem::drawCaret(QPainter* painter) const {
    if (!m_editing || !m_textItem) return;
    const QRectF r = m_textItem->textCursor().rect();
    if (r.isEmpty()) return;
    painter->save();
    painter->setPen(QPen(QColor(31, 39, 51), 1.4));
    painter->drawLine(QPointF(r.left(), r.top()), QPointF(r.left(), r.bottom()));
    painter->restore();
}

void MarkdownItem::drawCaret(QPainter* painter) const {
    if (!m_editing) return;
    const QTextBlock block = m_cursor.block();
    const QTextLayout* layout = block.layout();
    if (!layout) return;
    const int offset = m_cursor.position() - block.position();
    const int lineNo = layout->lineNumberForTextPosition(offset);
    const QTextLine line = layout->lineAt(lineNo);
    if (!line.isValid()) return;
    const qreal x = line.x() + line.cursorToX(offset);
    const QRectF lineRect = line.rect();
    painter->save();
    painter->setPen(QPen(QColor(31, 39, 51), 1.4));
    painter->drawLine(QPointF(x, lineRect.top()), QPointF(x, lineRect.bottom()));
    painter->restore();
}

