    for (int i = 0; i < m_m; ++i) {
        int base = 1 + i * 3;
        if (base + 2 >= static_cast<int>(tokens.size())) break;
        bool ok = false;
        int u = tokens[base].toInt(&ok);
        if (!ok) continue;
        int v = tokens[base + 1].toInt(&ok);
        if (!ok) continue;
        int w = tokens[base + 2].toInt(&ok);
        if (!ok) continue;
        addEdge(u, v, w, 0);
        if (!m_options.directed) addEdge(v, u, w, 1);
        ++index;
    }

    m_frames.push_back({ActionType::FS_DONE, tot, 0, 0, 0, {}, QString("共插入 %1 条边").arg(tot), QString("tot = %1").arg(tot)});

    m_frames.push_back({ActionType::FS_TRAVERSE, m_src, 0, 0, 0, {}, QString("从结点 %1 出发遍历邻接表").arg(m_src), QString("for (i = head[%1]; i; i = nxt[i])").arg(m_src)});
