void MarkdownItem::relayoutPreview() {
    if (!m_sourceItem || !m_textItem) return;
    const qreal sourceH = m_sourceItem->boundingRect().height();
    if (m_editing) {
        m_textItem->setPos(0, sourceH + 10.0);
        m_textItem->show();
    } else {
        m_textItem->setPos(0, 0);
    }
    prepareGeometryChange();
}

