               qPrintable(boxes[i].tag), qPrintable(boxes[j].tag), area,
               boxes[i].rect.x(), boxes[i].rect.y(),
               boxes[i].rect.width(), boxes[i].rect.height());
    }
}

int conflicts = 0;
for (size_t i = 0; i < boxes.size(); ++i) {
    for (size_t j = i + 1; j < boxes.size(); ++j) {
        const bool cellPair = boxes[i].tag.startsWith("cell:") && boxes[j].tag.startsWith("cell:");
        if (cellPair && sameRow(boxes[i], boxes[j])) continue;
        const bool nodePair = boxes[i].tag.startsWith("node:") && boxes[j].tag.startsWith("node:");
        if (nodePair) continue;
        const bool nodeCell = (boxes[i].tag.startsWith("node:") && boxes[j].tag.startsWith("cell:"))
                           || (boxes[j].tag.startsWith("node:") && boxes[i].tag.startsWith("cell:"));
        if (nodeCell) continue;
        const double area = overlapArea(boxes[i].rect, boxes[j].rect);
        if (area < minArea) continue;
        ++conflicts;
        printf("  [%s] OVERLAP '%s' <-> '%s' area=%.0f  (%.0f,%.0f %.0fx%.0f)\n", label,
               qPrintable(boxes[i].tag), qPrintable(boxes[j].tag), area,
               boxes[i].rect.x(), boxes[i].rect.y(),
               boxes[i].rect.width(), boxes[i].rect.height());
    }
}

