    painter->drawLine(0, len, 0, 4);
    painter->drawLine(0, 4, -7, 14);
    painter->drawLine(0, 4, 7, 14);
    painter->drawText(QRectF(m_labelOffset.x() - w / 2.0, m_labelOffset.y(), w, 20), Qt::AlignCenter, label);
}

    if (m_direction == Left || m_direction == Right) {
        double sign = (m_direction == Right) ? 1.0 : -1.0;
        painter->drawLine(-len * sign, 0, 0, 0);
        painter->drawLine(0, 0, -9 * sign, -7);
        painter->drawLine(0, 0, -9 * sign, 7);
        painter->drawText(QRectF(m_labelOffset.x() - w / 2.0, m_labelOffset.y(), w, 20), Qt::AlignCenter, label);
        return;
    }
    if (m_direction == Down) {
        painter->drawLine(0, -len, 0, 0);
        painter->drawLine(0, 0, -7, -10);
        painter->drawLine(0, 0, 7, -10);
        painter->drawText(QRectF(m_labelOffset.x() - w / 2.0, m_labelOffset.y(), w, 20), Qt::AlignCenter, label);
        return;
    }
    painter->drawLine(0, len, 0, 0);
    painter->drawLine(0, 0, -7, 10);
    painter->drawLine(0, 0, 7, 10);
    painter->drawText(QRectF(m_labelOffset.x() - w / 2.0, m_labelOffset.y(), w, 20), Qt::AlignCenter, label);
}

    static QPointF defaultLabelOffset(Direction dir) {
        if (dir == Left || dir == Right) return QPointF(-38.0, -10.0);
        if (dir == Down) return QPointF(0.0, -24.0);
        return QPointF(0.0, 30.0);
    }
};

