}

void ComboOption::mousePressEvent(QMouseEvent* event) {
    if (event->button() == Qt::LeftButton) {
        emit picked();
        event->accept();
        return;
    }
    QWidget::mousePressEvent(event);
}

void ComboOption::enterEvent(QEnterEvent* event) {
    m_hover = true;
    syncAnimations();
    update();
    QWidget::enterEvent(event);
}

void ComboOption::leaveEvent(QEvent* event) {
    m_hover = false;
    m_pressed = false;
    syncAnimations();
    update();
    QWidget::leaveEvent(event);
}

void ComboOption::mousePressEvent(QMouseEvent* event) {
    if (event->button() == Qt::LeftButton) {
        m_pressed = true;
        syncAnimations();
        update();
        event->accept();
        return;
    }
    QWidget::mousePressEvent(event);
}

void ComboOption::mouseReleaseEvent(QMouseEvent* event) {
    if (event->button() == Qt::LeftButton) {
        const bool wasPressed = m_pressed;
        m_pressed = false;
        syncAnimations();
        update();
        if (wasPressed && rect().contains(event->pos())) {
            emit picked();
        }
        event->accept();
        return;
    }
    QWidget::mouseReleaseEvent(event);
}

