bool TextBoxItem::placeCaretAt(const QPointF& scenePos) {
    if (!m_editing || !m_textItem) return false;
    const QPointF local = mapFromScene(scenePos);
    const QPointF inner = m_textItem->mapFromParent(local);
    const QTextBlock block = m_textItem->document()->findBlock(inner);
    if (!block.isValid()) return false;
    const QTextLayout* layout = block.layout();
    if (!layout) return false;
    const int lineIndex = layout->lineForTextPosition(block.position()).lineNumber();
    QTextLine line = layout->lineAt(lineIndex);
    if (!line.isValid()) return false;
    for (int i = lineIndex; i < layout->lineCount(); ++i) {
        line = layout->lineAt(i);
        if (!line.isValid()) break;
        if (inner.y() <= line.rect().bottom()) break;
    }
    const int offset = line.xToCursor(inner.x(), QTextLine::CursorBetweenCharacters);
    m_cursor.setPosition(block.position() + offset);
    m_textItem->setTextCursor(m_cursor);
    rebuildDocument();
    update();
    return true;
}

void TextBoxItem::drawCaret(QPainter* painter) const {
    if (!m_editing || !m_textItem) return;
    const QRectF caret = caretRect();
    if (caret.isEmpty()) return;
    painter->save();
    painter->setPen(QPen(m_textColor, 1.4));
    painter->drawLine(caret.topLeft(), caret.bottomLeft());
    painter->restore();
}

