bool TextBoxItem::placeCaretAt(const QPointF& scenePos) {
    if (!m_editing || !m_textItem) return false;
    const QPointF local = mapFromScene(scenePos);
    const QPointF inner = m_textItem->mapFromParent(local);
    const QTextBlock block = InlineTextEdit::blockAtPoint(m_textItem, inner);
    if (!block.isValid()) return false;
    const int offset = InlineTextEdit::cursorOffsetAtPoint(m_textItem, inner, block);
    m_cursor.setPosition(block.position() + offset);
    m_textItem->setTextCursor(m_cursor);
    rebuildDocument();
    update();
    return true;
}

bool TextBoxItem::placeCaretAt(const QPointF& scenePos) {
    if (!m_editing || !m_textItem) return false;
    const QPointF local = mapFromScene(scenePos);
    const QPointF inner = m_textItem->mapFromParent(local);
    const int position = InlineTextEdit::positionAtPoint(m_textItem, inner);
    if (position < 0) return false;
    m_cursor.setPosition(position);
    m_textItem->setTextCursor(m_cursor);
    rebuildDocument();
    update();
    return true;
}

bool MarkdownItem::placeCaretAt(const QPointF& scenePos) {
    if (!m_editing || !m_sourceItem) return false;
    const QPointF local = mapFromScene(scenePos);
    const QPointF inner = m_sourceItem->mapFromParent(local);
    const QTextBlock block = InlineTextEdit::blockAtPoint(m_sourceItem, inner);
    if (!block.isValid()) return false;
    const int offset = InlineTextEdit::cursorOffsetAtPoint(m_sourceItem, inner, block);
    m_cursor.setPosition(block.position() + offset);
    if (m_sourceItem) {
        m_sourceItem->setTextCursor(m_cursor);
        m_sourceItem->setTextWidth(320.0);
        m_sourceItem->adjustSize();
    }
    m_source = m_editor.toPlainText();
    rebuildPreview();
    relayoutPreview();
    notifyContentChanged();
    update();
    return true;
}

