void ComboOption::paintGlassTile(QPainter& painter, const QRectF& box) {
    const QColor accent = m_accent;
    const qreal hp = m_hoverProgress;
    const qreal pp = m_pressProgress;

    const double radius = 12.0;
    QRectF r = box.adjusted(1.5, 1.5, -1.5, -1.5);
    r.translate(0, 1.0 * pp);

    QPainterPath path;
    path.addRoundedRect(r, radius, radius);

    QColor fill = QColor(255, 255, 255, m_selected ? 132 : static_cast<int>(54 + 52 * hp));
    painter.setPen(Qt::NoPen);
    painter.setBrush(fill);
    painter.drawPath(path);

    QColor edge = QColor(255, 255, 255, m_selected ? 190 : static_cast<int>(96 + 70 * hp));
    painter.setPen(QPen(edge, 1.0));
    painter.setBrush(Qt::NoBrush);
    painter.drawPath(path);

    if (m_selected) {
        QLinearGradient grad(r.topLeft(), r.bottomLeft());
        grad.setColorAt(0.0, mixAlpha(accent, 74));
        grad.setColorAt(1.0, mixAlpha(accent, 26));
        painter.setPen(Qt::NoPen);
        painter.setBrush(grad);
        painter.drawPath(path);
    }

    QColor textColor = m_selected ? accent.darker(132) : mixColor(QColor(44, 52, 66), accent.darker(124), hp);
    painter.setFont(font());
    painter.setPen(textColor);
    painter.drawText(r.adjusted(14.0, 0, -10.0, 0), Qt::AlignVCenter | Qt::AlignLeft, m_text);
}

void ComboOption::paintMinimalTile(QPainter& painter, const QRectF& box) {
    const QColor accent = m_accent;
    const qreal hp = m_hoverProgress;
    const qreal pp = m_pressProgress;

    const double radius = 7.0;
    QRectF r = box.adjusted(2.0, 2.0, -2.0, -2.0);
    r.translate(0, 1.0 * pp);

    QPainterPath path;
    path.addRoundedRect(r, radius, radius);
    if (hp > 0.01 || m_selected) {
        painter.setPen(Qt::NoPen);
        painter.setBrush(QColor(241, 245, 251, m_selected ? 255 : static_cast<int>(210 * hp)));
        painter.drawPath(path);
    }

    if (m_selected) {
        const double d = 6.0;
        const QPointF dot(r.left() + 12.0 - d / 2.0, r.center().y() - d / 2.0);
        painter.setPen(Qt::NoPen);
        painter.setBrush(accent);
        painter.drawEllipse(dot, d / 2.0, d / 2.0);
    }

    QColor textColor = m_selected ? accent.darker(126)
                                   : mixColor(UiTheme::textSecondary(), UiTheme::textPrimary(), hp);
    painter.setFont(font());
    painter.setPen(textColor);
    painter.drawText(r.adjusted(m_selected ? 20.0 : 12.0, 0, -10.0, 0),
                     Qt::AlignVCenter | Qt::AlignLeft, m_text);
}

