void ComboPopupFrame::paintEvent(QPaintEvent*) {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setPen(Qt::NoPen);
    if (!m_card) return;
    const QRectF cardRect(m_card->geometry());
    const double radius = 20.0;
    const int layers = 12;
    for (int i = layers; i >= 1; --i) {
        const double spread = i * 2.2;
        const QRectF r = cardRect.adjusted(-spread, -spread * 0.6, spread, spread * 0.6);
        const int alpha = static_cast<int>(5.0 * (1.0 - (i - 1) / static_cast<double>(layers)));
        if (alpha <= 0) continue;
        painter.setBrush(QColor(24, 40, 68, alpha));
        painter.drawRoundedRect(r, radius + spread, radius + spread);
    }
}

void MyComboBox::computeColumnWidth() {
    m_columnWidth = 120;
    if (m_groups.isEmpty()) return;
    const int columns = 3;
    std::vector<int> widest(columns, 0);
    for (const Group& group : m_groups) {
        int cell = 0;
        for (int index : group.indices) {
            if (index < 0 || index >= m_items.size()) { ++cell; continue; }
            const QFont f = UiFonts::forText(m_items[index], 9);
            const QFontMetrics fm(f);
            const int need = fm.horizontalAdvance(m_items[index]) + 34;
            const int col = cell % columns;
            if (need > widest[col]) widest[col] = need;
            ++cell;
        }
    }
    int total = 0;
    for (int w : widest) total += w;
    if (total <= 0) return;
    m_columnWidth = widest.empty() ? 120 : widest[0];
    for (int col = 1; col < columns; ++col) {
        if (widest[col] > m_columnWidth) m_columnWidth = widest[col];
    }
    m_columnWidth = qBound(120, m_columnWidth, 240);
}

