void GraphNode::commitEdit() {
    if (m_editor.isNull()) return;
    QString text = m_editor->toPlainText().trimmed();
    destroyEditor(m_editor);
    update();
    if (text.isEmpty()) return;
    bool ok = false;
    int parsed = text.toInt(&ok);
    if (ok) {
        value = parsed;
        if (!customValueText.isEmpty()) {
            setCustomValueText(QString::number(parsed));
            setCenterText(QString::number(parsed));
        } else if (!centerValueText.isEmpty()) {
            setCenterText(QString::number(parsed));
        } else {
            setValueText(text);
        }
    } else {
        if (!customValueText.isEmpty()) {
            setCustomValueText(text);
            setCenterText(text);
        } else if (!centerValueText.isEmpty()) {
            setCenterText(text);
        } else {
            setValueText(text);
        }
    }
    update();
    emit valueEdited(id, text);
}

