    QImage img(bounds.size().toSize(), QImage::Format_ARGB32);
    img.fill(Qt::white);
    QPainter p(&img);
    p.setRenderHint(QPainter::Antialiasing);
    scene.render(&p, QRectF(QPointF(0, 0), img.size()), bounds);
    p.end();
    img.save(QString("newmod_%1.png").arg(tag).toUtf8().constData());
    return !img.isNull();
}

