MatrixBlock::MatrixBlock(int r, int c, QGraphicsItem* parent) : QGraphicsObject(parent) {
    rows = qMax(1, r);
    cols = qMax(1, c);
    data.resize(rows);

MatrixBlock::MatrixBlock(int r, int c, QGraphicsItem* parent) : QGraphicsObject(parent) {
    rows = qMax(1, r);
    cols = qMax(1, c);
    cellHeight = cell;
