    int ox = qMax(0, static_cast<int>(tl.x()));
    int oy = qMax(0, static_cast<int>(tl.y()));
    QImage sub = shot.copy(ox, oy, w, h);
    sub.scaled(w * 2, h * 2).save(file);
    printf("saved %s\n", file);
}

