void IModule::retargetPointer(PointerBlock* ptr, QGraphicsItem* anchor) {
    if (!ptr) return;
    if (anchor) {
        ptr->setAnchorItem(anchor, false);
    } else {
        ptr->clearAnchor();
    }
    retargetPointerTo(ptr, anchor, ptr->anchorOffset());
}

