}

if (frame.type == ActionType::HF_SORT_DROP) {
    if (frame.u < 0) {
        for (size_t i = 0; i < m_arrayCells.size(); ++i) {
            m_arrayCells[i]->color = kHfLeafSorted;
            m_arrayCells[i]->update();
        }
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(40, 140, 70));
        }
        return;
    }

    const int slot = frame.u;
    const int nodeId = frame.v;
    const std::vector<int>& perm = frame.group;
    if (perm.size() != m_arrayCells.size()) return;

    for (size_t i = 0; i < perm.size(); ++i) {
        ArrayBlock* cell = m_arrayCells[i];
        const int id = perm[i];
        if (id >= 0 && id < static_cast<int>(m_nodes.size())) {
            cell->setCustomValue(QString::number(m_nodes[id].weight));
        }
        cell->color = (static_cast<int>(i) == slot) ? kHfLeafSorted : kHfLeaf;
        cell->update();
    }

    ArrayBlock* dest = (slot >= 0 && slot < static_cast<int>(m_arrayCells.size()))
                           ? m_arrayCells[slot] : nullptr;
    if (dest && m_animated) {
        const QPointF start = QPointF(kArrayLeft + dest->pos().x() / kCellW * kCellW + kCellW / 2.0,
                                      kArrayY - 72.0);
        const long long weight = (nodeId >= 0 && nodeId < static_cast<int>(m_nodes.size()))
                                     ? m_nodes[nodeId].weight : 0;
        playBubbleFlight(start, dest->pos(), static_cast<int>(weight), 520);
    }
    if (m_noteText) m_noteText->setPlainText(frame.explanation);
    return;
}

void IModule::playMoveTo(std::vector<QGraphicsItem*> items, std::vector<QPointF> targets, int duration) {
    if (items.empty() || items.size() != targets.size()) return;
    std::vector<QPointF> starts;
    for (QGraphicsItem* item : items) {
        if (!item) continue;
        starts.push_back(item->pos());
    }
    if (!m_animated) {
        for (size_t i = 0; i < items.size(); ++i) {
            if (!items[i]) continue;
            items[i]->setPos(targets[i]);
        }
        return;
    }
    for (QGraphicsItem* item : items) {
        if (!item) continue;
        auto it = m_rowShiftAnims.find(item);
        if (it != m_rowShiftAnims.end() && it->second) {
            it->second->stop();
            it->second->deleteLater();
            m_rowShiftAnims.erase(it);
        }
    }
    QVariantAnimation* anim = new QVariantAnimation();
    anim->setDuration(duration);
    anim->setStartValue(0.0);
    anim->setEndValue(1.0);
    anim->setEasingCurve(QEasingCurve::InOutCubic);
    QObject::connect(anim, &QVariantAnimation::valueChanged, [items, starts, targets](const QVariant& progress) {
        const qreal t = progress.toReal();
        for (size_t i = 0; i < items.size(); ++i) {
            if (!items[i]) continue;
            const QPointF s = starts[i];
            const QPointF e = targets[i];
            items[i]->setPos(s.x() + (e.x() - s.x()) * t, s.y() + (e.y() - s.y()) * t);
        }
    });
    QObject::connect(anim, &QVariantAnimation::finished, [this, items]() {
        for (QGraphicsItem* item : items) {
            if (!item) continue;
            m_rowShiftAnims.erase(item);
        }
    });
    for (QGraphicsItem* item : items) {
        if (!item) continue;
        m_rowShiftAnims[item] = QPointer<QVariantAnimation>(anim);
    }
    anim->start(QAbstractAnimation::DeleteWhenStopped);
}

